package com.oms.inventory;
import com.oms.inventory.service.impl.*;
import com.oms.inventory.model.entity.WmsInventoryBatch;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class StockCareTest {
 OrderStockTest f;StockCareService care;QualityInventoryService quality;
 @BeforeAll static void start(){OrderStockTest.start();}
 @AfterAll static void stop(){OrderStockTest.stop();}
 @BeforeEach void setup(){f=new OrderStockTest();f.clear();for(String t:Arrays.asList("oms_quality_order","oms_stock_care_event","oms_stock_care_line","oms_stock_care"))f.db.update("DELETE FROM "+t);care=f.context.getBean(StockCareService.class);quality=f.context.getBean(QualityInventoryService.class);f.seed(10,0);WmsInventoryBatch b=new WmsInventoryBatch();b.setCompanyCode("VERIFY");b.setSkuSn("A");b.setStoreCode("W1");b.setBatchCode("B1");b.setZpActualNumber(0);b.setCpActualNumber(3);f.inventory.receivePurchase(b,"WMS_RECEIPT_9001");}
 Map<String,Object> m(Object...a){Map<String,Object> r=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)r.put(a[i].toString(),a[i+1]);return r;}
 Map<String,Object> reserve(String sn,String type,int qty){return m("document_sn",sn,"purpose","RETURN","actor","tester","lines",Collections.singletonList(m("line_key",1,"sku_sn","A","store_code","W1","batch_code","B1","inventory_type",type,"quantity",qty,"origin_relation",type.equals("CP")?"WMS_RECEIPT_9001":"IN-1")));}
 Map<String,Object> post(String sn,String msg,int q){return m("document_sn",sn,"message_id",msg,"actor","WMS","lines",Collections.singletonList(m("line_key",1,"quantity",q)));}
 long n(String sql){return f.n(sql);}
 long batch(){return n("SELECT id FROM wms_inventory_batch WHERE sku_sn='A'");}
 Map<String,Object> qualityCmd(String action,String type,int q){return m("request_key",UUID.randomUUID().toString(),"action",action,"inventory_type",type,"quantity",q,"batch_id",batch(),"reason","仓库质量核对","evidence","仓库质检凭证 QA-001","warehouse_confirmed",true);}
 Map<String,Object> approve(long id){return quality.review("VERIFY",id,m("control_version",1,"decision","APPROVE","reason","已核对原批次与质检凭证"),"reviewer");}
 @Test void purchaseBadIsFrozenAndOtherReceiptContractsArePreserved(){assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(10,n("SELECT available_stock FROM oms_inventory"));assertEquals(3,n("SELECT frozen_stock FROM oms_inventory"));WmsInventoryBatch b=new WmsInventoryBatch();b.setCompanyCode("VERIFY");b.setSkuSn("A");b.setStoreCode("W1");b.setBatchCode("OTHER");b.setZpActualNumber(0);b.setCpActualNumber(1);f.inventory.receive(b,"OTHER_BUSINESS");assertEquals(11,n("SELECT available_stock FROM oms_inventory"));assertEquals(3,n("SELECT frozen_stock FROM oms_inventory"));assertThrows(IllegalArgumentException.class,()->f.inventory.receivePurchase(b,"OTHER_BUSINESS"));}
 @Test void badReturnHoldThenPartialPostAndReleasePreserveAllBuckets(){Map<String,Object> cmd=reserve("CGTBAD","CP",3);care.execute("VERIFY","reserve",cmd);care.execute("VERIFY","reserve",cmd);assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(3,n("SELECT allocated_stock FROM oms_inventory"));assertEquals(0,n("SELECT frozen_stock FROM oms_inventory"));care.execute("VERIFY","post",post("CGTBAD","M1",2));care.execute("VERIFY","post",post("CGTBAD","M1",2));care.execute("VERIFY","release",m("document_sn","CGTBAD","actor","tester"));assertEquals(11,n("SELECT total_stock FROM oms_inventory"));assertEquals(1,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(10,n("SELECT available_stock FROM oms_inventory"));assertEquals(0,n("SELECT allocated_stock FROM oms_inventory"));assertEquals(1,n("SELECT cp_available_number FROM wms_inventory_batch"));}
 @Test void overPostChangedMessageAndLatePostCannotStealStock(){care.execute("VERIFY","reserve",reserve("CGTOVER","ZP",4));assertThrows(IllegalArgumentException.class,()->care.execute("VERIFY","post",post("CGTOVER","X",5)));care.execute("VERIFY","post",post("CGTOVER","X",2));assertThrows(IllegalArgumentException.class,()->care.execute("VERIFY","post",post("CGTOVER","X",1)));care.execute("VERIFY","release",m("document_sn","CGTOVER","actor","tester"));assertThrows(IllegalArgumentException.class,()->care.execute("VERIFY","post",post("CGTOVER","LATE",1)));assertEquals(11,n("SELECT total_stock FROM oms_inventory"));}
 @Test void orderClaimsAreProtectedAndReserveFailureRollsBack(){f.execute("register",f.command("9019",9,true));f.execute("reserve",f.command("9019",9,true));assertThrows(IllegalArgumentException.class,()->care.execute("VERIFY","reserve",reserve("CGTCLAIM","ZP",2)));assertEquals(0,n("SELECT COUNT(*) FROM oms_stock_care"));assertEquals(0,n("SELECT zp_lock_number FROM wms_inventory_batch"));}
 @Test void returnRequiresOriginalSuccessfulReceiptAndCompany(){Map<String,Object> cmd=reserve("CGTORIGIN","ZP",2);((Map)((List)cmd.get("lines")).get(0)).put("origin_relation","NOT_A_RECEIPT");assertThrows(IllegalArgumentException.class,()->care.execute("VERIFY","reserve",cmd));assertEquals(0,n("SELECT COUNT(*) FROM oms_stock_care"));assertFalse((Boolean)care.report("OTHER","CGTORIGIN").get("exists"));}
 @Test void sameRequestCannotChangeItsGradeOrAmount(){care.execute("VERIFY","reserve",reserve("CGTIDENTITY","ZP",2));assertThrows(IllegalArgumentException.class,()->care.execute("VERIFY","reserve",reserve("CGTIDENTITY","ZP",3)));assertEquals(2,n("SELECT zp_lock_number FROM wms_inventory_batch"));}
 @Test void concurrentReturnsCannotOverdrawBatch() throws Exception {ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Callable<Boolean>> tasks=new ArrayList<>();for(String sn:Arrays.asList("CGTRACE1","CGTRACE2"))tasks.add(()->{try{care.execute("VERIFY","reserve",reserve(sn,"ZP",7));return true;}catch(IllegalArgumentException e){return false;}});int success=0;for(Future<Boolean> x:pool.invokeAll(tasks))if(x.get())success++;assertEquals(1,success);assertEquals(7,n("SELECT zp_lock_number FROM wms_inventory_batch"));assertEquals(3,n("SELECT available_stock FROM oms_inventory"));}finally{pool.shutdownNow();}}
 @Test void qualityFreezeAndPartialUnfreezeUseOnlyOriginalHold(){long id=quality.create("VERIFY",qualityCmd("FREEZE","ZP",4),"tester");Map<String,Object> frozen=approve(id);assertEquals(6,n("SELECT available_stock FROM oms_inventory"));assertEquals(7,n("SELECT frozen_stock FROM oms_inventory"));Map<String,Object> release=qualityCmd("UNFREEZE","ZP",2);release.put("source_sn",frozen.get("quality_sn"));approve(quality.create("VERIFY",release,"tester"));assertEquals(8,n("SELECT available_stock FROM oms_inventory"));assertEquals(5,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(2,n("SELECT zp_lock_number FROM wms_inventory_batch"));release=qualityCmd("UNFREEZE","ZP",3);release.put("source_sn",frozen.get("quality_sn"));long next=quality.create("VERIFY",release,"tester");assertThrows(IllegalArgumentException.class,()->approve(next));assertEquals("DRAFT",quality.detail("VERIFY",next).get("state"));}
 @Test void badFreezeDoesNotBecomeGoodOrIncreaseFrozenTwice(){long id=quality.create("VERIFY",qualityCmd("FREEZE","CP",2),"tester");Map<String,Object> d=approve(id);assertEquals(3,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(10,n("SELECT available_stock FROM oms_inventory"));Map<String,Object> q=qualityCmd("UNFREEZE","CP",2);q.put("source_sn",d.get("quality_sn"));approve(quality.create("VERIFY",q,"tester"));assertEquals(3,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(0,n("SELECT cp_lock_number FROM wms_inventory_batch"));}
 @Test void conversionNeedsWarehouseEvidenceAndApprovalAndIsIdempotent(){Map<String,Object> cmd=qualityCmd("CP_TO_ZP","CP",2);cmd.put("warehouse_confirmed",false);assertThrows(IllegalArgumentException.class,()->quality.create("VERIFY",cmd,"tester"));cmd.put("warehouse_confirmed",true);long id=quality.create("VERIFY",cmd,"tester");assertEquals(id,quality.create("VERIFY",cmd,"tester"));assertEquals(10,n("SELECT zp_actual_number FROM wms_inventory_batch"));approve(id);assertThrows(IllegalArgumentException.class,()->approve(id));assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(12,n("SELECT available_stock FROM oms_inventory"));assertEquals(1,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(12,n("SELECT zp_actual_number FROM wms_inventory_batch"));assertEquals(1,n("SELECT cp_actual_number FROM wms_inventory_batch"));assertEquals(2,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type LIKE 'QUALITY_%'"));}
 @Test void rejectAndCrossCompanyReviewCannotChangeStock(){long id=quality.create("VERIFY",qualityCmd("FREEZE","ZP",2),"tester");assertThrows(IllegalArgumentException.class,()->quality.review("OTHER",id,m("control_version",1,"decision","APPROVE","reason","test"),"other"));quality.review("VERIFY",id,m("control_version",1,"decision","REJECT","reason","凭证不完整"),"reviewer");assertEquals(10,n("SELECT available_stock FROM oms_inventory"));assertEquals(0,n("SELECT zp_lock_number FROM wms_inventory_batch"));}
 @Test void frozenOrReservedBadCannotBeConverted(){approve(quality.create("VERIFY",qualityCmd("FREEZE","CP",3),"tester"));long id=quality.create("VERIFY",qualityCmd("CP_TO_ZP","CP",1),"tester");assertThrows(IllegalArgumentException.class,()->approve(id));assertEquals(3,n("SELECT cp_actual_number FROM wms_inventory_batch"));}
 @Test void channelSellableSnapshotTracksFreezeAndConversionWithoutCountingBadStock(){f.db.update("UPDATE oms_channel_inventory SET quota_stock=20 WHERE company_code='VERIFY' AND channel_id=1 AND sku_sn='A'");PlatformStockSnapshot snapshots=f.context.getBean(PlatformStockSnapshot.class);Map<String,Object> input=m("channel_id",1,"allow_public_stock",true,"allowed_warehouses",Collections.singletonList("W1"),"components",Collections.singletonList(m("sku_sn","A","quantity",1)));assertEquals(10L,snapshots.snapshot("VERIFY",input).get("available"));approve(quality.create("VERIFY",qualityCmd("FREEZE","ZP",4),"tester"));assertEquals(6L,snapshots.snapshot("VERIFY",input).get("available"));approve(quality.create("VERIFY",qualityCmd("CP_TO_ZP","CP",2),"tester"));assertEquals(8L,snapshots.snapshot("VERIFY",input).get("available"));assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(5,n("SELECT frozen_stock FROM oms_inventory"));}
 @Test void sameSkuBatchMixedGradeReceiptHasDistinctStockJournalIdentities(){Map<String,Object> cmd=reserve("CGTMIXED","ZP",2);List<Map<String,Object>> ls=new ArrayList<>((List<Map<String,Object>>)cmd.get("lines"));Map<String,Object> bad=new LinkedHashMap<>((Map<String,Object>)((List)reserve("CGTANY","CP",1).get("lines")).get(0));bad.put("line_key",2);ls.add(bad);cmd.put("lines",ls);care.execute("VERIFY","reserve",cmd);Map<String,Object> event=m("document_sn","CGTMIXED","message_id","SAME_MESSAGE","actor","WMS","lines",Arrays.asList(m("line_key",1,"quantity",2),m("line_key",2,"quantity",1)));care.execute("VERIFY","post",event);care.execute("VERIFY","post",event);assertEquals(10,n("SELECT total_stock FROM oms_inventory"));assertEquals(8,n("SELECT available_stock FROM oms_inventory"));assertEquals(2,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(2,n("SELECT COUNT(DISTINCT request_id) FROM wms_inventory_change_history WHERE operation_type='RETURN_OUT'"));}
 @Test void partialMixedCancellationReleasesOnlyEachOriginalGrade(){Map<String,Object> cmd=reserve("CGTMIXCANCEL","ZP",2);List<Map<String,Object>> ls=new ArrayList<>((List<Map<String,Object>>)cmd.get("lines"));Map<String,Object> bad=new LinkedHashMap<>((Map<String,Object>)((List)reserve("CGTANY","CP",2).get("lines")).get(0));bad.put("line_key",2);ls.add(bad);cmd.put("lines",ls);care.execute("VERIFY","reserve",cmd);care.execute("VERIFY","post",m("document_sn","CGTMIXCANCEL","message_id","PART","actor","WMS","lines",Collections.singletonList(m("line_key",1,"quantity",2))));care.execute("VERIFY","release",m("document_sn","CGTMIXCANCEL","actor","tester"));assertEquals(11,n("SELECT total_stock FROM oms_inventory"));assertEquals(8,n("SELECT available_stock FROM oms_inventory"));assertEquals(3,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(0,n("SELECT zp_lock_number+cp_lock_number FROM wms_inventory_batch"));}
 Map<String,Object> recovery(String msg,String type,int q,long source){return m("document_sn","CGTRECOVER","message_id",msg,"actor","WMS","lines",Collections.singletonList(m("line_key",1,"inventory_type",type,"quantity",q,"origin_relation","PURCHASE_RECLAIM_"+source)));}
 @Test void independentRecoveryPreservesOutboundAndUsesActualQuality(){care.execute("VERIFY","reserve",reserve("CGTRECOVER","ZP",3));Map<String,Object> preview=((List<Map<String,Object>>)care.report("VERIFY","CGTRECOVER").get("lines")).get(0);assertEquals(7L,((Number)preview.get("zp_available_number")).longValue());assertEquals(3L,((Number)preview.get("cp_available_number")).longValue());care.execute("VERIFY","post",post("CGTRECOVER","OUT",3));care.execute("VERIFY","recover",recovery("IN1","ZP",2,101));care.execute("VERIFY","recover",recovery("IN1","ZP",2,101));care.execute("VERIFY","recover",recovery("IN2","CP",1,102));assertEquals(13,n("SELECT total_stock FROM oms_inventory"));assertEquals(9,n("SELECT available_stock FROM oms_inventory"));assertEquals(4,n("SELECT frozen_stock FROM oms_inventory"));assertEquals(3,n("SELECT recovered_quantity FROM oms_stock_care_line"));assertEquals(1,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='RETURN_OUT'"));assertEquals(2,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE operation_type='RECEIVE' AND relation_sn LIKE 'PURCHASE_RECLAIM_%'"));assertThrows(IllegalArgumentException.class,()->care.execute("VERIFY","recover",recovery("EXTRA","ZP",1,103)));}
 @Test void overRecoveryRollsBackWholeMixedQualityReceipt(){care.execute("VERIFY","reserve",reserve("CGTRECOVER","ZP",3));care.execute("VERIFY","post",post("CGTRECOVER","OUT",3));Map<String,Object> cmd=recovery("MIXED","ZP",2,201);cmd.put("lines",Arrays.asList(m("line_key",1,"inventory_type","ZP","quantity",2,"origin_relation","PURCHASE_RECLAIM_201"),m("line_key",1,"inventory_type","CP","quantity",2,"origin_relation","PURCHASE_RECLAIM_202")));assertThrows(IllegalArgumentException.class,()->care.execute("VERIFY","recover",cmd));assertEquals(10,n("SELECT total_stock FROM oms_inventory"));assertEquals(0,n("SELECT recovered_quantity FROM oms_stock_care_line"));assertEquals(0,n("SELECT COUNT(*) FROM wms_inventory_change_history WHERE relation_sn LIKE 'PURCHASE_RECLAIM_%'"));}
 @Test void concurrentRecoveryCannotExceedOriginalActualOut()throws Exception{care.execute("VERIFY","reserve",reserve("CGTRECOVER","ZP",3));care.execute("VERIFY","post",post("CGTRECOVER","OUT",3));ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Callable<Boolean>> jobs=new ArrayList<>();for(int i=1;i<=2;i++){final int j=i;jobs.add(()->{try{care.execute("VERIFY","recover",recovery("IN"+j,"ZP",2,300+j));return true;}catch(IllegalArgumentException e){return false;}});}int wins=0;for(Future<Boolean> x:pool.invokeAll(jobs))if(x.get())wins++;assertEquals(1,wins);assertEquals(12,n("SELECT total_stock FROM oms_inventory"));}finally{pool.shutdownNow();}}

}
